import {directions,makeStudio} from './kit.js';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
let selected=0;const views=[];const el=id=>document.getElementById(id);
const cards=el('cards');directions.forEach((d,i)=>{const b=document.createElement('button');b.className='card';b.type='button';b.setAttribute('aria-pressed',i===0);b.innerHTML=`<div class="thumb" id="thumb-${i}" aria-hidden="true"></div>${i===0?'<span class="badge">Starting direction</span>':''}<div class="card-info"><h3><span class="card-number">0${i+1}</span>${d.name}</h3><p>${d.subtitle}</p></div>`;b.addEventListener('click',()=>{selected=i;update();});cards.appendChild(b);});
function notice(message){el('status').textContent=message;clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>el('status').textContent='',3500);}
let hero,controls;
function values(){return {clay:el('clay').checked,context:el('context').checked,light:el('light').value,angle:Number(el('sun').value),exposure:Number(el('exposure').value)}}
function update(){const d=directions[selected],v=values();el('look-title').textContent=d.name;el('look-description').textContent=d.description;el('stage-label').textContent=`0${selected+1} / ${d.name.toUpperCase()}`;el('swatches').innerHTML=d.colors.map(c=>`<span style="background:${c}" title="${c}"></span>`).join('');el('sun-value').value=v.angle+'°';el('exposure-value').value=v.exposure.toFixed(2);document.querySelectorAll('.card').forEach((b,i)=>b.setAttribute('aria-pressed',selected===i));if(hero)hero.update(selected,v.clay,v.context,v.light,v.angle,v.exposure);views.forEach((view,i)=>view.update(i,v.clay,v.context,v.light,v.angle,v.exposure));}
try{hero=makeStudio(el('viewport'),0,true);controls=new OrbitControls(hero.camera,hero.renderer.domElement);controls.target.set(0,1.6,0);controls.enablePan=false;controls.minZoom=.65;controls.maxZoom=2;controls.minPolarAngle=.25;controls.maxPolarAngle=Math.PI/2.15;controls.addEventListener('change',hero.render);controls.update();directions.forEach((_,i)=>views.push(makeStudio(el('thumb-'+i),i)));}catch(error){console.error(error);el('render-error').hidden=false;el('export').disabled=true;}
['light','sun','exposure','clay','context'].forEach(id=>el(id).addEventListener('input',update));el('reset-camera').addEventListener('click',()=>{if(!hero)return;hero.camera.position.set(12,10,14);hero.camera.zoom=1;controls.target.set(0,1.6,0);controls.update();hero.resize();notice('Matched three-quarter camera restored.');});
el('export').addEventListener('click',()=>{if(!hero)return;hero.render();const a=document.createElement('a');a.download=`wf-market-${directions[selected].id}-${el('light').value}-v001.png`;a.href=hero.renderer.domElement.toDataURL('image/png');a.click();notice('Saved the current camera and lighting as a PNG.');});update();
